//! Test-only plugin that misbehaves on request. `issues.get(number)` selects the behaviour;
//! `pull-requests.list-feedback` and `reply` return fixed data after a `GET` that maps `429` to
//! `rate-limited`. The host tests in `crates/df-plugins/tests` build it for `wasm32-wasip2`.

#![expect(clippy::same_length_and_capacity, reason = "generated by wit-bindgen")]

wit_bindgen::generate!({
    path: "../../contract/wit/integrations",
    world: "forge",
    generate_all,
});

use darkfactory::integrations::types::{Error, IssueRef, PullRequestRef, RateLimit, RepoRef};
use darkfactory::integrations::webhook_signature;
use exports::darkfactory::integrations::issues::{
    Comment, Guest as IssuesGuest, Issue, IssueState,
};
use exports::darkfactory::integrations::pull_requests::{
    Author, AuthorRole, Feedback, Guest as PullRequestsGuest, NewPullRequest, PostedComment,
    PrComment, PullRequest, PullRequestUpdate, Review, ReviewComment, ReviewThread, ReviewVerdict,
};
use exports::darkfactory::integrations::webhooks::{
    CiFailed, Guest as WebhooksGuest, ParsedEvent, WebhookEvent,
};

pub struct Probe;

/// Number of environment variables the plugin sees.
pub const ENVIRONMENT: u64 = 1;
/// Spins forever.
pub const LOOP: u64 = 2;
/// Allocates far more memory than any sane limit.
pub const ALLOCATE: u64 = 3;
/// Writes a line to stderr.
pub const STDERR: u64 = 4;
/// `GET <base-url>/echo` with its own `Authorization: Bearer fake`; the body is the status code.
pub const OWN_AUTHORIZATION: u64 = 5;
/// `GET http://<repo owner>/`, the owner standing in for a `host:port`; fails with `transport` if
/// the host denies it.
pub const OTHER_HOST: u64 = 6;
/// The configured `base-url` as body.
pub const BASE_URL: u64 = 7;
/// The result of `webhook-signature.verify` outside a webhook call as body.
pub const VERIFY_OUTSIDE_WEBHOOK: u64 = 8;

/// Minimal blocking `GET` over `wasi:http`; returns the status code.
fn get(base_url: &str, path: &str, authorization: Option<&str>) -> Result<u16, Error> {
    use wasi::http::outgoing_handler;
    use wasi::http::types::{Fields, Method, OutgoingRequest, Scheme};

    let transport =
        |what: &str, e: &dyn std::fmt::Debug| Error::Transport(format!("{what}: {e:?}"));
    let (scheme, authority) = base_url
        .split_once("://")
        .ok_or_else(|| Error::Config(format!("invalid URL {base_url}")))?;
    let headers = Fields::new();
    if let Some(value) = authorization {
        headers
            .append("authorization", value.as_bytes())
            .map_err(|e| transport("header", &e))?;
    }
    let request = OutgoingRequest::new(headers);
    request
        .set_method(&Method::Get)
        .and(request.set_scheme(Some(&match scheme {
            "https" => Scheme::Https,
            "http" => Scheme::Http,
            other => Scheme::Other(other.to_string()),
        })))
        .and(request.set_authority(Some(authority)))
        .and(request.set_path_with_query(Some(path)))
        .map_err(|()| Error::Internal("invalid request target".to_string()))?;
    let future = outgoing_handler::handle(request, None).map_err(|e| transport("send", &e))?;
    future.subscribe().block();
    let response = future
        .get()
        .and_then(Result::ok)
        .ok_or_else(|| Error::Internal("response future not ready".to_string()))?
        .map_err(|e| transport("response", &e))?;
    Ok(response.status())
}

impl IssuesGuest for Probe {
    #[expect(
        clippy::print_stderr,
        reason = "the probe writes to stderr to test that the host forwards it"
    )]
    fn get(id: IssueRef) -> Result<Issue, Error> {
        let body = match id.number {
            ENVIRONMENT => format!("env={}", std::env::vars().count()),
            LOOP => loop {
                std::hint::black_box(());
            },
            ALLOCATE => {
                let mut big = vec![1u8; 512 * 1024 * 1024];
                if let Some(first) = big.first_mut() {
                    *first = 2;
                }
                format!("allocated {}", big.len())
            }
            STDERR => {
                eprintln!("hello from stderr");
                String::new()
            }
            OWN_AUTHORIZATION => {
                let base_url = wasi::config::store::get("base-url")
                    .ok()
                    .flatten()
                    .ok_or_else(|| Error::Config("`base-url` is not configured".to_string()))?;
                get(&base_url, "/echo", Some("Bearer fake"))?.to_string()
            }
            OTHER_HOST => get(&format!("http://{}", id.repo.owner), "/", None)?.to_string(),
            BASE_URL => wasi::config::store::get("base-url")
                .ok()
                .flatten()
                .unwrap_or_default(),
            VERIFY_OUTSIDE_WEBHOOK => webhook_signature::verify(&[0; 32]).to_string(),
            _ => String::new(),
        };
        Ok(Issue {
            id,
            url: String::new(),
            title: String::new(),
            body,
            state: IssueState::Open,
            labels: Vec::new(),
        })
    }

    fn add_comment(_id: IssueRef, _body: String) -> Result<Comment, Error> {
        Err(Error::Internal("not supported by the probe".to_string()))
    }
}

impl PullRequestsGuest for Probe {
    fn create(_request: NewPullRequest) -> Result<PullRequest, Error> {
        Err(Error::Internal("not supported by the probe".to_string()))
    }

    fn find_open(_: RepoRef, _: String, _: String) -> Result<Option<PullRequest>, Error> {
        Ok(None)
    }

    fn get(_: PullRequestRef) -> Result<PullRequest, Error> {
        Err(Error::Internal("not supported by the probe".to_string()))
    }

    fn update(_: PullRequestRef, _: PullRequestUpdate) -> Result<PullRequest, Error> {
        Err(Error::Internal("not supported by the probe".to_string()))
    }

    fn list_feedback(id: PullRequestRef, since: Option<String>) -> Result<Feedback, Error> {
        rate_limited_on_429(&format!("/pulls/{}/feedback", id.number))?;
        let at = "2026-11-02T10:00:00Z".to_string();
        let url = |anchor: &str| format!("https://forge.test/o/r/pulls/{}#{anchor}", id.number);
        let author = |login: &str, role| Author {
            login: login.to_string(),
            role,
        };
        Ok(Feedback {
            comments: vec![PrComment {
                id: format!("c{}", id.number),
                author: author("alice", AuthorRole::Member),
                body: format!("since {}", since.unwrap_or_default()),
                url: url(&format!("c{}", id.number)),
                created_at: at.clone(),
                updated_at: at.clone(),
            }],
            reviews: vec![Review {
                id: "r1".to_string(),
                author: author("mallory", AuthorRole::Outside),
                verdict: ReviewVerdict::ChangesRequested,
                body: "please change".to_string(),
                url: url("r1"),
                submitted_at: at.clone(),
                updated_at: "2026-11-02T11:00:00Z".to_string(),
            }],
            threads: vec![ReviewThread {
                id: "t1".to_string(),
                path: "src/lib.rs".to_string(),
                line: Some(12),
                resolved: true,
                comments: vec![ReviewComment {
                    id: "rc1".to_string(),
                    author: author("factory-bot", AuthorRole::Bot),
                    body: "done".to_string(),
                    url: url("rc1"),
                    created_at: at.clone(),
                    updated_at: at,
                }],
            }],
            truncated: true,
        })
    }

    /// Echoes the PR number and `thread` as id and `body` as URL.
    fn reply(id: PullRequestRef, thread: String, body: String) -> Result<PostedComment, Error> {
        rate_limited_on_429(&format!("/pulls/{}/reply", id.number))?;
        Ok(PostedComment {
            id: format!("{}:{thread}", id.number),
            url: body,
        })
    }
}

/// `GET <base-url><path>`; a `429` becomes `rate-limited` with a zero `retry-after`.
fn rate_limited_on_429(path: &str) -> Result<(), Error> {
    let base_url = wasi::config::store::get("base-url")
        .ok()
        .flatten()
        .ok_or_else(|| Error::Config("`base-url` is not configured".to_string()))?;
    match get(&base_url, path, None)? {
        429 => Err(Error::RateLimited(RateLimit {
            retry_after_seconds: Some(0),
            message: "slow down".to_string(),
        })),
        _ => Ok(()),
    }
}

/// `handle-webhook` selects its behaviour by the header `x-probe-mode`:
/// `verify` checks the hex signature in `x-probe-signature`, `skip` returns an event without
/// checking, `http` verifies and then requests `https://forge.test/`, `invalid` rejects the
/// payload. Events are one `ci-failed` on `https://forge.test/o/r`, branch `main`.
impl WebhooksGuest for Probe {
    fn handle_webhook(
        headers: Vec<(String, String)>,
        _body: Vec<u8>,
    ) -> Result<Vec<ParsedEvent>, Error> {
        let header = |name: &str| {
            headers
                .iter()
                .find(|(k, _)| k.eq_ignore_ascii_case(name))
                .map(|(_, v)| v.clone())
                .unwrap_or_default()
        };
        let verify = || {
            let signature = hex::decode(header("x-probe-signature")).unwrap_or_default();
            if webhook_signature::verify(&signature) {
                Ok(())
            } else {
                Err(Error::Unauthorized("signature mismatch".to_string()))
            }
        };
        match header("x-probe-mode").as_str() {
            "verify" => verify()?,
            "skip" => {}
            "http" => {
                verify()?;
                get("https://forge.test", "/", None)?;
            }
            "invalid" => return Err(Error::InvalidInput("not a probe payload".to_string())),
            other => return Err(Error::Internal(format!("unknown mode `{other}`"))),
        }
        Ok(vec![ParsedEvent {
            repo_url: "https://forge.test/o/r".to_string(),
            event: WebhookEvent::CiFailed(CiFailed {
                repo: RepoRef {
                    owner: "o".to_string(),
                    name: "r".to_string(),
                },
                head: "main".to_string(),
                check: "ci".to_string(),
                url: String::new(),
            }),
        }])
    }

    fn whoami() -> Result<String, Error> {
        Ok("probe-bot".to_string())
    }

    /// `alice` is a member, everyone else outside.
    fn author_role(_repo: RepoRef, login: String) -> Result<AuthorRole, Error> {
        Ok(if login == "alice" {
            AuthorRole::Member
        } else {
            AuthorRole::Outside
        })
    }
}

#[cfg(target_arch = "wasm32")]
export!(Probe);
